-- Run once in Supabase SQL Editor. Then create users in Authentication > Users.
create extension if not exists pgcrypto;
create table public.profiles(id uuid primary key references auth.users(id) on delete cascade,full_name text not null,email text not null unique,role text not null default 'employee' check(role in ('employee','manager','admin')),annual_leave_allowance integer not null default 18 check(annual_leave_allowance>=0),created_at timestamptz not null default now());
create table public.projects(id uuid primary key default gen_random_uuid(),name text not null,client_name text not null,created_at timestamptz not null default now());
create table public.tasks(id uuid primary key default gen_random_uuid(),title text not null,description text default '',assignee_id uuid references public.profiles(id),project_id uuid references public.projects(id),created_by uuid references public.profiles(id),due_date date,priority text not null default 'Medium' check(priority in ('Low','Medium','High','Critical')),status text not null default 'To do' check(status in ('To do','In progress','Submitted','Revision','Completed','Approved')),created_at timestamptz not null default now());
create table public.submissions(id uuid primary key default gen_random_uuid(),task_id uuid not null references public.tasks(id) on delete cascade,user_id uuid not null references public.profiles(id),file_path text not null,file_name text not null,note text default '',status text not null default 'Pending' check(status in ('Pending','Approved','Revision requested')),reviewed_by uuid references public.profiles(id),created_at timestamptz not null default now());
create table public.leave_requests(id uuid primary key default gen_random_uuid(),user_id uuid not null references public.profiles(id),start_date date not null,end_date date not null,reason text not null,status text not null default 'Pending' check(status in ('Pending','Approved','Rejected')),reviewed_by uuid references public.profiles(id),created_at timestamptz not null default now(),check(end_date>=start_date));
create table public.attendance(id uuid primary key default gen_random_uuid(),user_id uuid not null references public.profiles(id),work_date date not null,clock_in timestamptz not null,clock_out timestamptz,created_at timestamptz not null default now(),unique(user_id,work_date),check(clock_out is null or clock_out>=clock_in));
-- SECURITY DEFINER avoids recursive RLS checks on profiles.
create function public.is_manager() returns boolean language sql stable security definer set search_path='' as $$select exists(select 1 from public.profiles where id=(select auth.uid()) and role in ('admin','manager'))$$;
revoke all on function public.is_manager() from public;grant execute on function public.is_manager() to authenticated;
create function public.is_assigned(t uuid) returns boolean language sql stable security definer set search_path='' as $$select exists(select 1 from public.tasks where id=t and assignee_id=(select auth.uid()))$$;
revoke all on function public.is_assigned(uuid) from public;grant execute on function public.is_assigned(uuid) to authenticated;
alter table public.profiles enable row level security;alter table public.projects enable row level security;alter table public.tasks enable row level security;alter table public.submissions enable row level security;alter table public.leave_requests enable row level security;alter table public.attendance enable row level security;
create policy profiles_read on public.profiles for select to authenticated using (id=(select auth.uid()) or public.is_manager());
create policy projects_read on public.projects for select to authenticated using (public.is_manager() or exists(select 1 from public.tasks where project_id=projects.id and assignee_id=(select auth.uid())));
create policy projects_insert on public.projects for insert to authenticated with check(public.is_manager());
create policy projects_update on public.projects for update to authenticated using(public.is_manager()) with check(public.is_manager());
create policy tasks_read on public.tasks for select to authenticated using(public.is_manager() or assignee_id=(select auth.uid()));
create policy tasks_insert on public.tasks for insert to authenticated with check(public.is_manager());
create policy tasks_update_manager on public.tasks for update to authenticated using(public.is_manager()) with check(public.is_manager());
-- Employee can update task status, but not reassign or edit deadlines; guarded by trigger.
create function public.guard_task_update() returns trigger language plpgsql security definer set search_path='' as $$begin if not public.is_manager() then if old.assignee_id is distinct from auth.uid() or new.id is distinct from old.id or new.title is distinct from old.title or new.description is distinct from old.description or new.assignee_id is distinct from old.assignee_id or new.project_id is distinct from old.project_id or new.created_by is distinct from old.created_by or new.due_date is distinct from old.due_date or new.priority is distinct from old.priority or new.created_at is distinct from old.created_at or new.status not in ('To do','In progress','Submitted') then raise exception 'Employees may only update their own task progress';end if;end if;return new;end$$;
create trigger guard_task_update before update on public.tasks for each row execute function public.guard_task_update();
create policy tasks_update_employee on public.tasks for update to authenticated using(assignee_id=(select auth.uid())) with check(assignee_id=(select auth.uid()));
create policy submissions_read on public.submissions for select to authenticated using(public.is_manager() or user_id=(select auth.uid()));
create policy submissions_insert on public.submissions for insert to authenticated with check(user_id=(select auth.uid()) and public.is_assigned(task_id) and status='Pending' and reviewed_by is null and file_path like (select auth.uid())::text||'/%');
create policy submissions_update on public.submissions for update to authenticated using(public.is_manager()) with check(public.is_manager());
create policy leave_read on public.leave_requests for select to authenticated using(public.is_manager() or user_id=(select auth.uid()));
create policy leave_insert on public.leave_requests for insert to authenticated with check(user_id=(select auth.uid()) and status='Pending' and reviewed_by is null);
create policy leave_update on public.leave_requests for update to authenticated using(public.is_manager()) with check(public.is_manager());
create policy attendance_read on public.attendance for select to authenticated using(public.is_manager() or user_id=(select auth.uid()));
create policy attendance_insert on public.attendance for insert to authenticated with check(user_id=(select auth.uid()) and work_date=current_date and clock_out is null and abs(extract(epoch from (clock_in-now())))<120);
create policy attendance_update on public.attendance for update to authenticated using(user_id=(select auth.uid())) with check(user_id=(select auth.uid()));
create function public.guard_attendance_update() returns trigger language plpgsql security definer set search_path='' as $$begin if new.user_id is distinct from old.user_id or new.work_date is distinct from old.work_date or new.clock_in is distinct from old.clock_in or new.created_at is distinct from old.created_at or old.clock_out is not null or new.clock_out is null or abs(extract(epoch from (new.clock_out-now())))>120 then raise exception 'Only current clock-out is allowed';end if;return new;end$$;
create trigger guard_attendance_update before update on public.attendance for each row execute function public.guard_attendance_update();
insert into storage.buckets(id,name,public,file_size_limit,allowed_mime_types) values('deliverables','deliverables',false,52428800,array['image/jpeg','image/png','image/webp','image/gif','video/mp4','video/quicktime','video/webm','application/pdf','application/zip']) on conflict(id) do nothing;
create policy deliverables_upload on storage.objects for insert to authenticated with check(bucket_id='deliverables' and (storage.foldername(name))[1]=(select auth.uid())::text and exists(select 1 from public.profiles where id=(select auth.uid())));
create policy deliverables_read on storage.objects for select to authenticated using(bucket_id='deliverables' and (public.is_manager() or (storage.foldername(name))[1]=(select auth.uid())::text));
